import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.Cs5aHXsR.js";var i=JSON.parse(`{"title":"Tools","description":"","frontmatter":{},"headers":[],"relativePath":"reference/tools.md","filePath":"reference/tools.md","lastUpdated":1788362422000}`),a={name:`reference/tools.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to “Tools”">​</a></h1><p>One section per tool. All 71 are registered unless you say otherwise: <code>WOODPECKER_ALLOW_TOOLS</code> and <code>WOODPECKER_DENY_TOOLS</code> narrow the list, and <code>essential</code> selects the ones marked <strong>essential</strong> below — see <a href="/guide/configuration#choosing-the-tools-that-load">choosing the tools that load</a>.</p><p>Every tool declares an <code>outputSchema</code> and answers with <code>structuredContent</code> beside the text block, so a client can use a result without parsing prose. The tools that report pushed content carry <code>untrusted: true</code> and <code>source: &quot;woodpecker&quot;</code> as fields of that object — build logs are the raw stdout of arbitrary containers.</p><p>Three markers recur:</p><ul><li><strong>essential</strong> — part of the <code>essential</code> preset.</li><li>🛡 <strong>admin</strong> — needs an instance administrator. Woodpecker answers any other account with 403; <code>get_current_user</code> says which you have.</li><li>👤 <strong>asks a person</strong> — through MCP elicitation, a dialog the model cannot answer on its behalf, and which nothing proceeds without. Where the client cannot show one, the first call returns a <code>confirm_token</code> bound to those exact arguments and does nothing else; a second call carrying it acts. That token is single-use, expires after five minutes, and proves only that the call was made twice with the same arguments — the fallback text says so. <code>ELICITATION=false</code> takes it deliberately; it never removes the guard. See <a href="/guide/approval">Asking a person</a>.</li></ul><p>Repository ids are numeric. <code>lookup_repository</code> turns an <code>owner/name</code> pair into one; nothing in the web UI shows it.</p><h2 id="repositories" tabindex="-1">Repositories <a class="header-anchor" href="#repositories" aria-label="Permalink to “Repositories”">​</a></h2><h3 id="list-repositories" tabindex="-1"><code>list_repositories</code> <a class="header-anchor" href="#list-repositories" aria-label="Permalink to “list_repositories”">​</a></h3><p><strong>essential</strong> — Repositories this account can see. <code>scope: &quot;instance&quot;</code> lists every repository on the server (🛡 admin) instead. <code>include_inactive: true</code> also lists repositories that exist in the forge but were never activated, which is where <code>forge_remote_id</code> for <code>activate_repository</code> comes from; it is noticeably slower, because Woodpecker refreshes them from the forge.</p><p>Parameters: <code>scope</code>, <code>include_inactive</code>, <code>name</code>, <code>page</code>, <code>per_page</code>.</p><h3 id="get-repository" tabindex="-1"><code>get_repository</code> <a class="header-anchor" href="#get-repository" aria-label="Permalink to “get_repository”">​</a></h3><p><strong>essential</strong> — One repository with everything Woodpecker stores about it: trusted flags, timeout, approval mode, config file path, extension endpoints.</p><p>Parameters: <code>repo_id</code>.</p><h3 id="lookup-repository" tabindex="-1"><code>lookup_repository</code> <a class="header-anchor" href="#lookup-repository" aria-label="Permalink to “lookup_repository”">​</a></h3><p>Resolves <code>owner/name</code> to a repository id. A repository that exists in the forge but was never activated answers 404 — see <code>list_repositories</code>.</p><p>Parameters: <code>full_name</code>.</p><h3 id="get-repository-permissions" tabindex="-1"><code>get_repository_permissions</code> <a class="header-anchor" href="#get-repository-permissions" aria-label="Permalink to “get_repository_permissions”">​</a></h3><p>What this account may do here: pull, push, admin. Inherited from the forge, so this is the answer to &quot;why did that return 403&quot;.</p><p>Parameters: <code>repo_id</code>.</p><h3 id="list-repository-branches" tabindex="-1"><code>list_repository_branches</code> <a class="header-anchor" href="#list-repository-branches" aria-label="Permalink to “list_repository_branches”">​</a></h3><p>Branches as Woodpecker sees them in the forge. Worth calling before <code>trigger_pipeline</code>, which answers a branch that does not exist with a bare 400.</p><p>Parameters: <code>repo_id</code>, <code>page</code>, <code>per_page</code>.</p><h3 id="list-pull-requests" tabindex="-1"><code>list_pull_requests</code> <a class="header-anchor" href="#list-pull-requests" aria-label="Permalink to “list_pull_requests”">​</a></h3><p>Open pull requests and their index — the number a ref like <code>refs/pull/42/head</code> refers to.</p><p>Parameters: <code>repo_id</code>, <code>page</code>, <code>per_page</code>.</p><h3 id="activate-repository" tabindex="-1"><code>activate_repository</code> <a class="header-anchor" href="#activate-repository" aria-label="Permalink to “activate_repository”">​</a></h3><p>Turns Woodpecker on for a forge repository: installs the webhook and lets pipelines run. Takes the <strong>forge-side</strong> id, not a Woodpecker <code>repo_id</code> (there is none yet) and not an <code>owner/name</code> pair.</p><p>Parameters: <code>forge_remote_id</code>.</p><h3 id="update-repository" tabindex="-1"><code>update_repository</code> <a class="header-anchor" href="#update-repository" aria-label="Permalink to “update_repository”">​</a></h3><p>👤 (when granting trust, lowering <code>require_approval</code> or going <code>public</code>) — Changes Woodpecker&#39;s settings for a repository. Only the fields you pass are touched. <code>trusted_network</code>, <code>trusted_volumes</code> and <code>trusted_security</code> are folded into the nested object the API expects; all three are admin-only and <code>trusted_security</code> lets a pipeline take over the agent host.</p><p>Three changes are two-step, and all three for the same reason: they widen what somebody else&#39;s code can reach. Granting any <code>trusted_*</code> flag. Lowering <code>require_approval</code> — the setting that decides whether a fork&#39;s pipeline waits for a person before it runs with this repository&#39;s secrets, which is the gate <a href="#approve-pipeline"><code>approve_pipeline</code></a> exists to hold. Setting <code>visibility</code> to <code>public</code>, which makes the logs those builds write readable by anyone. Naming either of the last two costs one extra read, because &quot;lowering&quot; is a comparison with the current setting; tightening them, withdrawing trust and every other field still apply on the first call.</p><p>Parameters: <code>repo_id</code>, <code>config_file</code>, <code>timeout</code>, <code>visibility</code>, <code>allow_pr</code>, <code>allow_deploy</code>, <code>require_approval</code>, <code>cancel_previous_pipeline_events</code>, <code>trusted_network</code>, <code>trusted_volumes</code>, <code>trusted_security</code>, <code>confirm_token</code>.</p><h3 id="repair-repository" tabindex="-1"><code>repair_repository</code> <a class="header-anchor" href="#repair-repository" aria-label="Permalink to “repair_repository”">​</a></h3><p>👤 (instance scope only) — Re-installs the forge webhook and refreshes the stored repository data. This is the fix for &quot;pushes stopped starting pipelines&quot; after a rename or a change of Woodpecker&#39;s own URL. <code>scope: &quot;instance&quot;</code> does it for every repository, calls the forge once per repository, and is two-step for that reason.</p><p>Parameters: <code>repo_id</code>, <code>scope</code>, <code>confirm_token</code>.</p><h3 id="move-repository" tabindex="-1"><code>move_repository</code> <a class="header-anchor" href="#move-repository" aria-label="Permalink to “move_repository”">​</a></h3><p>👤 — Points Woodpecker at a repository that moved to a different owner or name in the forge. It does <strong>not</strong> move anything in the forge; do that first, then call this so Woodpecker follows.</p><p>Parameters: <code>repo_id</code>, <code>to</code>, <code>confirm_token</code>.</p><h3 id="chown-repository" tabindex="-1"><code>chown_repository</code> <a class="header-anchor" href="#chown-repository" aria-label="Permalink to “chown_repository”">​</a></h3><p>👤 — Makes this account the repository&#39;s owner in Woodpecker. The owner&#39;s forge token is what Woodpecker uses to read the repository and report build status, so this is the fix when the previous owner left.</p><p>Asked about because of what the ownership <em>is</em>: every pipeline of this repository afterwards runs under the calling account&#39;s forge token, so its reach over the forge becomes this repository&#39;s reach. <code>delete_user</code> already cites that in its own reasoning; the tool that performs the transfer did not ask.</p><p>Parameters: <code>repo_id</code>, <code>confirm_token</code>.</p><h3 id="delete-repository" tabindex="-1"><code>delete_repository</code> <a class="header-anchor" href="#delete-repository" aria-label="Permalink to “delete_repository”">​</a></h3><p>👤 — Removes a repository from Woodpecker with its pipelines, logs, secrets, registries and cron jobs. The forge repository is untouched.</p><p>Parameters: <code>repo_id</code>, <code>confirm_token</code>.</p><h2 id="pipelines" tabindex="-1">Pipelines <a class="header-anchor" href="#pipelines" aria-label="Permalink to “Pipelines”">​</a></h2><h3 id="list-pipelines" tabindex="-1"><code>list_pipelines</code> <a class="header-anchor" href="#list-pipelines" aria-label="Permalink to “list_pipelines”">​</a></h3><p><strong>essential</strong> — A repository&#39;s pipelines, newest first, summarised: number, status, event, branch, author, timings, and the subject line of the commit message. Note that <code>number</code> — not the pipeline id — is what every other pipeline tool takes.</p><p>Parameters: <code>repo_id</code>, <code>branch</code>, <code>event</code>, <code>status</code>, <code>ref</code>, <code>before</code>, <code>after</code>, <code>page</code>, <code>per_page</code>.</p><h3 id="get-pipeline" tabindex="-1"><code>get_pipeline</code> <a class="header-anchor" href="#get-pipeline" aria-label="Permalink to “get_pipeline”">​</a></h3><p><strong>essential</strong> — One pipeline with its workflows and steps, including each step&#39;s id, state and exit code. The step id is what <code>get_step_logs</code> needs.</p><p>Parameters: <code>repo_id</code>, <code>number</code>.</p><h3 id="get-pipeline-config" tabindex="-1"><code>get_pipeline_config</code> <a class="header-anchor" href="#get-pipeline-config" aria-label="Permalink to “get_pipeline_config”">​</a></h3><p>The pipeline YAML this run was built from, decoded — the config that actually ran, not the one currently in the branch.</p><p>Parameters: <code>repo_id</code>, <code>number</code>.</p><h3 id="get-pipeline-metadata" tabindex="-1"><code>get_pipeline_metadata</code> <a class="header-anchor" href="#get-pipeline-metadata" aria-label="Permalink to “get_pipeline_metadata”">​</a></h3><p>The metadata Woodpecker exposes to the pipeline itself: the <code>CI_*</code> environment a step sees, plus the previous pipeline of the same workflow. Useful when a step behaves differently than its config suggests.</p><p>Parameters: <code>repo_id</code>, <code>number</code>.</p><h3 id="list-queued-pipelines" tabindex="-1"><code>list_queued_pipelines</code> <a class="header-anchor" href="#list-queued-pipelines" aria-label="Permalink to “list_queued_pipelines”">​</a></h3><p>Pipelines waiting in the server queue across all repositories — what is stuck, and behind what. <code>get_queue_info</code> adds the agent side of the same picture.</p><p>No parameters.</p><h3 id="trigger-pipeline" tabindex="-1"><code>trigger_pipeline</code> <a class="header-anchor" href="#trigger-pipeline" aria-label="Permalink to “trigger_pipeline”">​</a></h3><p><strong>essential</strong> — Starts a pipeline on a branch, with event <code>manual</code>. It runs the config as it is in that branch right now. A branch that does not exist is a bare 400, so check <code>list_repository_branches</code> first. <code>variables</code> is a flat string map; a nested object is rejected by the API.</p><p>Parameters: <code>repo_id</code>, <code>branch</code>, <code>message</code>, <code>variables</code>.</p><h3 id="restart-pipeline" tabindex="-1"><code>restart_pipeline</code> <a class="header-anchor" href="#restart-pipeline" aria-label="Permalink to “restart_pipeline”">​</a></h3><p><strong>essential</strong> — Runs an existing pipeline again, at the same commit and with the config it used then. The re-run gets a new number; the original is kept. <code>event</code> and <code>deploy_to</code> override how the re-run is treated.</p><p>Parameters: <code>repo_id</code>, <code>number</code>, <code>event</code>, <code>deploy_to</code>.</p><h3 id="cancel-pipeline" tabindex="-1"><code>cancel_pipeline</code> <a class="header-anchor" href="#cancel-pipeline" aria-label="Permalink to “cancel_pipeline”">​</a></h3><p><strong>essential</strong> — Stops a pending or running pipeline. Its steps are killed where they are, so anything half-written stays half-written. It can be restarted afterwards, which is why this one is not two-step.</p><p>Parameters: <code>repo_id</code>, <code>number</code>.</p><h3 id="approve-pipeline" tabindex="-1"><code>approve_pipeline</code> <a class="header-anchor" href="#approve-pipeline" aria-label="Permalink to “approve_pipeline”">​</a></h3><p>👤 — Releases a pipeline waiting for approval and lets it run. Read what you are approving: pipelines are usually blocked because they come from a fork, and approving one runs that fork&#39;s code with this repository&#39;s secrets. Two-step for that reason, and because the model usually arrives here holding a build log — which is written by whoever can open the pull request being approved.</p><p>Parameters: <code>repo_id</code>, <code>number</code>, <code>confirm_token</code>.</p><h3 id="decline-pipeline" tabindex="-1"><code>decline_pipeline</code> <a class="header-anchor" href="#decline-pipeline" aria-label="Permalink to “decline_pipeline”">​</a></h3><p>Refuses a pipeline waiting for approval. It ends as <code>declined</code> and never runs.</p><p>Parameters: <code>repo_id</code>, <code>number</code>.</p><h3 id="delete-pipeline" tabindex="-1"><code>delete_pipeline</code> <a class="header-anchor" href="#delete-pipeline" aria-label="Permalink to “delete_pipeline”">​</a></h3><p>👤 — Removes a pipeline and everything attached to it, including its logs. A running pipeline cannot be deleted — cancel it first.</p><p>Parameters: <code>repo_id</code>, <code>number</code>, <code>confirm_token</code>.</p><h2 id="logs" tabindex="-1">Logs <a class="header-anchor" href="#logs" aria-label="Permalink to “Logs”">​</a></h2><h3 id="get-step-logs" tabindex="-1"><code>get_step_logs</code> <a class="header-anchor" href="#get-step-logs" aria-label="Permalink to “get_step_logs”">​</a></h3><p><strong>essential</strong> — One step&#39;s output as text. Woodpecker returns it as an array of base64-encoded chunks with line numbers; this decodes them, puts them back in order and reports the step&#39;s exit code. Returns the <strong>last</strong> 200 lines by default, because that is where a failing step explains itself; <code>from: &quot;head&quot;</code> reads the other end. The result always says which window you got, how many lines exist, and how to widen it.</p><p>Parameters: <code>repo_id</code>, <code>number</code>, <code>step_id</code>, <code>limit</code>, <code>from</code>.</p><h3 id="delete-step-logs" tabindex="-1"><code>delete_step_logs</code> <a class="header-anchor" href="#delete-step-logs" aria-label="Permalink to “delete_step_logs”">​</a></h3><p>👤 — Deletes one step&#39;s stored output. The step and the pipeline stay. This is what you reach for when a step printed a secret — and then rotate the secret, because the log was readable until now and deleting it does not un-read it.</p><p>Parameters: <code>repo_id</code>, <code>number</code>, <code>step_id</code>, <code>confirm_token</code>.</p><h3 id="delete-pipeline-logs" tabindex="-1"><code>delete_pipeline_logs</code> <a class="header-anchor" href="#delete-pipeline-logs" aria-label="Permalink to “delete_pipeline_logs”">​</a></h3><p>👤 — The same for every step of a pipeline. The step results stay, so it still shows which step failed — just not why.</p><p>Parameters: <code>repo_id</code>, <code>number</code>, <code>confirm_token</code>.</p><h2 id="secrets" tabindex="-1">Secrets <a class="header-anchor" href="#secrets" aria-label="Permalink to “Secrets”">​</a></h2><p>Secrets exist at three levels. <code>scope</code> selects one: <code>&quot;repository&quot;</code> (needs <code>repo_id</code>), <code>&quot;organization&quot;</code> (needs <code>org_id</code>) or <code>&quot;global&quot;</code> (🛡 admin, needs neither). A pipeline sees the repository level first, then the organization, then global — so a name missing at one level may exist at the next.</p><h3 id="list-secrets" tabindex="-1"><code>list_secrets</code> <a class="header-anchor" href="#list-secrets" aria-label="Permalink to “list_secrets”">​</a></h3><p>Secrets at one level, with their events and image restrictions. Values are never part of the answer.</p><p>Parameters: <code>scope</code>, <code>repo_id</code>, <code>org_id</code>, <code>page</code>, <code>per_page</code>.</p><h3 id="get-secret" tabindex="-1"><code>get_secret</code> <a class="header-anchor" href="#get-secret" aria-label="Permalink to “get_secret”">​</a></h3><p>One secret&#39;s metadata. The value is not returned — Woodpecker strips it from every response, including the one right after creating it.</p><p>Parameters: <code>scope</code>, <code>repo_id</code>, <code>org_id</code>, <code>name</code>.</p><h3 id="create-secret" tabindex="-1"><code>create_secret</code> <a class="header-anchor" href="#create-secret" aria-label="Permalink to “create_secret”">​</a></h3><p>Creates a secret. The value is write-only, so store it somewhere else too. At least one event is required: the API has no defaults, and a secret without <code>pull_request</code> is invisible to pull-request builds.</p><p>Parameters: <code>scope</code>, <code>repo_id</code>, <code>org_id</code>, <code>name</code>, <code>value</code>, <code>events</code>, <code>images</code>, <code>note</code>.</p><h3 id="update-secret" tabindex="-1"><code>update_secret</code> <a class="header-anchor" href="#update-secret" aria-label="Permalink to “update_secret”">​</a></h3><p>👤 (when passing <code>value</code>, or widening who may read the secret) — Changes a secret. Passing <code>value</code> rotates it, which is two-step because the old value was never readable through the API and is gone once it is overwritten.</p><p>So is widening the exposure, and that is not cosmetics either: adding a <code>pull_request</code> event hands the secret to builds of code that arrived in a pull request, including from a fork, and emptying <code>images</code> removes the restriction on which container images may read it. Narrowing either, and editing the note, apply on the first call. <code>events</code> and <code>images</code> are replaced wholesale rather than merged, so pass the complete list — and naming either costs one extra read, because &quot;widening&quot; is a comparison with the secret&#39;s current setting.</p><p>Parameters: <code>scope</code>, <code>repo_id</code>, <code>org_id</code>, <code>name</code>, <code>value</code>, <code>events</code>, <code>images</code>, <code>note</code>, <code>confirm_token</code>.</p><h3 id="delete-secret" tabindex="-1"><code>delete_secret</code> <a class="header-anchor" href="#delete-secret" aria-label="Permalink to “delete_secret”">​</a></h3><p>👤 — Deletes a secret. The value cannot be recovered, and pipelines that read it will run without it.</p><p>Parameters: <code>scope</code>, <code>repo_id</code>, <code>org_id</code>, <code>name</code>, <code>confirm_token</code>.</p><h2 id="container-registries" tabindex="-1">Container registries <a class="header-anchor" href="#container-registries" aria-label="Permalink to “Container registries”">​</a></h2><p>Same three scopes as secrets. The address is the identifier — there is no separate name — so <code>docker.io</code> and <code>index.docker.io</code> are two entries.</p><h3 id="list-registries" tabindex="-1"><code>list_registries</code> <a class="header-anchor" href="#list-registries" aria-label="Permalink to “list_registries”">​</a></h3><p>Registry credentials at one level. Passwords are never returned.</p><p>Parameters: <code>scope</code>, <code>repo_id</code>, <code>org_id</code>, <code>page</code>, <code>per_page</code>.</p><h3 id="get-registry" tabindex="-1"><code>get_registry</code> <a class="header-anchor" href="#get-registry" aria-label="Permalink to “get_registry”">​</a></h3><p>One entry: address and username. The password is stripped by Woodpecker.</p><p>Parameters: <code>scope</code>, <code>repo_id</code>, <code>org_id</code>, <code>address</code>.</p><h3 id="create-registry" tabindex="-1"><code>create_registry</code> <a class="header-anchor" href="#create-registry" aria-label="Permalink to “create_registry”">​</a></h3><p>Stores credentials so pipelines can pull private images.</p><p>Parameters: <code>scope</code>, <code>repo_id</code>, <code>org_id</code>, <code>address</code>, <code>username</code>, <code>password</code>.</p><h3 id="update-registry" tabindex="-1"><code>update_registry</code> <a class="header-anchor" href="#update-registry" aria-label="Permalink to “update_registry”">​</a></h3><p>👤 (when passing <code>password</code>) — Changes username or password. The address cannot be changed — delete and re-create instead. Replacing the password is two-step for the same reason <a href="#delete-registry"><code>delete_registry</code></a> is: Woodpecker strips it from every response, so the value being overwritten is not readable anywhere and nothing brings it back. Correcting a username alone applies on the first call.</p><p>Parameters: <code>scope</code>, <code>repo_id</code>, <code>org_id</code>, <code>address</code>, <code>username</code>, <code>password</code>, <code>confirm_token</code>.</p><h3 id="delete-registry" tabindex="-1"><code>delete_registry</code> <a class="header-anchor" href="#delete-registry" aria-label="Permalink to “delete_registry”">​</a></h3><p>👤 — Removes stored credentials. Pipelines pulling private images from that registry start failing at the pull step.</p><p>Parameters: <code>scope</code>, <code>repo_id</code>, <code>org_id</code>, <code>address</code>, <code>confirm_token</code>.</p><h2 id="cron-jobs" tabindex="-1">Cron jobs <a class="header-anchor" href="#cron-jobs" aria-label="Permalink to “Cron jobs”">​</a></h2><p>A cron schedule is a <strong>five-field</strong> expression (<code>0 4 * * *</code> is 04:00 daily), a descriptor (<code>@daily</code>, <code>@hourly</code>, <code>@weekly</code>, <code>@monthly</code>, <code>@yearly</code>, <code>@midnight</code>) or <code>@every 30m</code>. There is no seconds field — a six-field expression is refused with &quot;expected exactly 5 fields, found 6&quot;.</p><p>Timezone defaults to UTC, and on the official container image that is the only value that works: it is distroless and carries no zoneinfo database, so anything else fails with &quot;unknown time zone&quot;. See the <a href="/guide/faq#setting-a-cron-timezone-fails-with-unknown-time-zone">FAQ</a>.</p><h3 id="list-crons" tabindex="-1"><code>list_crons</code> <a class="header-anchor" href="#list-crons" aria-label="Permalink to “list_crons”">​</a></h3><p>A repository&#39;s scheduled runs, with the next execution time of each.</p><p>Parameters: <code>repo_id</code>, <code>page</code>, <code>per_page</code>.</p><h3 id="get-cron" tabindex="-1"><code>get_cron</code> <a class="header-anchor" href="#get-cron" aria-label="Permalink to “get_cron”">​</a></h3><p>One cron job, including the variables it passes.</p><p>Parameters: <code>repo_id</code>, <code>cron_id</code>.</p><h3 id="create-cron" tabindex="-1"><code>create_cron</code> <a class="header-anchor" href="#create-cron" aria-label="Permalink to “create_cron”">​</a></h3><p>Schedules a pipeline run. It runs with event <code>cron</code>, so steps and secrets restricted to other events do not apply — a cron job whose steps all say <code>when: event: push</code> runs and does nothing.</p><p>Parameters: <code>repo_id</code>, <code>name</code>, <code>schedule</code>, <code>branch</code>, <code>timezone</code>.</p><h3 id="update-cron" tabindex="-1"><code>update_cron</code> <a class="header-anchor" href="#update-cron" aria-label="Permalink to “update_cron”">​</a></h3><p>Changes a cron job. <code>enabled: false</code> pauses a schedule without losing it.</p><p>Parameters: <code>repo_id</code>, <code>cron_id</code>, <code>name</code>, <code>schedule</code>, <code>branch</code>, <code>timezone</code>, <code>enabled</code>.</p><h3 id="run-cron" tabindex="-1"><code>run_cron</code> <a class="header-anchor" href="#run-cron" aria-label="Permalink to “run_cron”">​</a></h3><p>Runs the cron job&#39;s pipeline now, without waiting for its schedule and without changing it. This is how you test a nightly job without waiting a night.</p><p>Parameters: <code>repo_id</code>, <code>cron_id</code>.</p><h3 id="delete-cron" tabindex="-1"><code>delete_cron</code> <a class="header-anchor" href="#delete-cron" aria-label="Permalink to “delete_cron”">​</a></h3><p>👤 — Removes a schedule. Nothing will notice that the job stopped running, which is the failure mode of every deleted scheduled task.</p><p>Parameters: <code>repo_id</code>, <code>cron_id</code>, <code>confirm_token</code>.</p><h2 id="organizations" tabindex="-1">Organizations <a class="header-anchor" href="#organizations" aria-label="Permalink to “Organizations”">​</a></h2><h3 id="list-organizations" tabindex="-1"><code>list_organizations</code> <a class="header-anchor" href="#list-organizations" aria-label="Permalink to “list_organizations”">​</a></h3><p>🛡 — Organizations known to this instance. An entry with <code>is_user: true</code> is a personal account rather than a real organization; Woodpecker models both the same way, and org-level secrets work for both.</p><p>Parameters: <code>page</code>, <code>per_page</code>.</p><h3 id="get-organization" tabindex="-1"><code>get_organization</code> <a class="header-anchor" href="#get-organization" aria-label="Permalink to “get_organization”">​</a></h3><p>One organization by id.</p><p>Parameters: <code>org_id</code>.</p><h3 id="lookup-organization" tabindex="-1"><code>lookup_organization</code> <a class="header-anchor" href="#lookup-organization" aria-label="Permalink to “lookup_organization”">​</a></h3><p>Resolves an organization name to the id that org-level secrets, registries and agents need.</p><p>Parameters: <code>name</code>.</p><h3 id="get-organization-permissions" tabindex="-1"><code>get_organization_permissions</code> <a class="header-anchor" href="#get-organization-permissions" aria-label="Permalink to “get_organization_permissions”">​</a></h3><p>Member and admin flags for this account in that organization.</p><p>Parameters: <code>org_id</code>.</p><h3 id="delete-organization" tabindex="-1"><code>delete_organization</code> <a class="header-anchor" href="#delete-organization" aria-label="Permalink to “delete_organization”">​</a></h3><p>🛡👤 — Removes an organization with its org-level secrets, registries and agents. The forge and the repositories are untouched, but anything of theirs that relied on an org-level secret stops working.</p><p>Parameters: <code>org_id</code>, <code>confirm_token</code>.</p><h2 id="the-authenticated-account" tabindex="-1">The authenticated account <a class="header-anchor" href="#the-authenticated-account" aria-label="Permalink to “The authenticated account”">​</a></h2><h3 id="get-current-user" tabindex="-1"><code>get_current_user</code> <a class="header-anchor" href="#get-current-user" aria-label="Permalink to “get_current_user”">​</a></h3><p>Which account <code>WOODPECKER_TOKEN</code> belongs to, and whether it is an instance administrator. The first thing to call when a tool answers 403.</p><p>No parameters.</p><h3 id="get-pipeline-feed" tabindex="-1"><code>get_pipeline_feed</code> <a class="header-anchor" href="#get-pipeline-feed" aria-label="Permalink to “get_pipeline_feed”">​</a></h3><p>The activity feed: the latest pipeline of every repository this account can see, newest first. One request instead of <code>list_pipelines</code> per repository.</p><p>No parameters.</p><h2 id="users" tabindex="-1">Users <a class="header-anchor" href="#users" aria-label="Permalink to “Users”">​</a></h2><p>Woodpecker creates an account the first time someone logs in, so this is everyone who has ever used the instance rather than a managed roster. A login is only unique per forge, which is why <code>forge_id</code> is required where it is.</p><h3 id="list-users" tabindex="-1"><code>list_users</code> <a class="header-anchor" href="#list-users" aria-label="Permalink to “list_users”">​</a></h3><p>🛡 — Accounts known to this instance.</p><p>Parameters: <code>page</code>, <code>per_page</code>.</p><h3 id="get-user" tabindex="-1"><code>get_user</code> <a class="header-anchor" href="#get-user" aria-label="Permalink to “get_user”">​</a></h3><p>🛡 — One account by login. <code>forge_id</code> is required by the API; <code>list_users</code> and <code>list_forges</code> show it, and on a single-forge instance it is 1.</p><p>Parameters: <code>login</code>, <code>forge_id</code>, <code>forge_remote_id</code>.</p><h3 id="create-user" tabindex="-1"><code>create_user</code> <a class="header-anchor" href="#create-user" aria-label="Permalink to “create_user”">​</a></h3><p>🛡👤 (when granting admin) — Registers an account ahead of its first login. This creates nothing in the forge and grants no access there — it is how you make someone an administrator before they first log in. A login that does not match the forge&#39;s spelling creates a second, unused account rather than the one you meant.</p><p>The same field, and only that field, as <code>update_user</code> below. Until this was added, <code>update_user(admin: true)</code> asked and <code>create_user(admin: true)</code> did not — the same privilege by the same flag, with a dialog in front of one of them.</p><p>Parameters: <code>login</code>, <code>email</code>, <code>admin</code>, <code>confirm_token</code>.</p><h3 id="update-user" tabindex="-1"><code>update_user</code> <a class="header-anchor" href="#update-user" aria-label="Permalink to “update_user”">​</a></h3><p>🛡👤 (when granting admin) — Changes email or the admin flag. Granting <code>admin</code> gives full control of the instance, including every secret of every repository, which is why that one field asks. Correcting an email applies on the first call.</p><p>Parameters: <code>login</code>, <code>email</code>, <code>admin</code>, <code>confirm_token</code>.</p><h3 id="delete-user" tabindex="-1"><code>delete_user</code> <a class="header-anchor" href="#delete-user" aria-label="Permalink to “delete_user”">​</a></h3><p>🛡👤 — Removes an account. Repositories it owned keep pointing at a forge token that no longer exists, which shows up later as pipelines that stop starting — transfer them with <code>chown_repository</code> first.</p><p>Parameters: <code>login</code>, <code>forge_id</code>, <code>confirm_token</code>.</p><h2 id="agents" tabindex="-1">Agents <a class="header-anchor" href="#agents" aria-label="Permalink to “Agents”">​</a></h2><p>An agent&#39;s token is a credential: it is what a machine presents to register as a build agent, after which it receives pipeline workloads and their secrets. The API returns it in clear text on every read; this server redacts it everywhere except <code>create_agent</code>. See <a href="/guide/security#agent-tokens-are-redacted">security</a>.</p><h3 id="list-agents" tabindex="-1"><code>list_agents</code> <a class="header-anchor" href="#list-agents" aria-label="Permalink to “list_agents”">​</a></h3><p>🛡 (instance-wide) — Build agents with their platform, capacity, version and last contact — the call that answers &quot;why is nothing being built&quot;. With <code>org_id</code> it lists one organization&#39;s agents, which an organization admin may also do.</p><p>Parameters: <code>org_id</code>, <code>page</code>, <code>per_page</code>.</p><h3 id="get-agent" tabindex="-1"><code>get_agent</code> <a class="header-anchor" href="#get-agent" aria-label="Permalink to “get_agent”">​</a></h3><p>🛡 — One agent, token redacted. An agent that lost its token needs a new one, which means <code>delete_agent</code> and <code>create_agent</code>.</p><p>Parameters: <code>agent_id</code>.</p><h3 id="list-agent-tasks" tabindex="-1"><code>list_agent_tasks</code> <a class="header-anchor" href="#list-agent-tasks" aria-label="Permalink to “list_agent_tasks”">​</a></h3><p>🛡 — The work an agent is running right now: what is occupying a busy agent, and which pipeline to cancel.</p><p>Parameters: <code>agent_id</code>.</p><h3 id="create-agent" tabindex="-1"><code>create_agent</code> <a class="header-anchor" href="#create-agent" aria-label="Permalink to “create_agent”">​</a></h3><p>🛡 — Registers a new agent and <strong>returns its token</strong>, because that is the only way to get it. Put it straight into the agent&#39;s configuration. With <code>org_id</code> the agent only runs that organization&#39;s pipelines.</p><p>Parameters: <code>name</code>, <code>org_id</code>, <code>no_schedule</code>, <code>custom_labels</code>.</p><h3 id="update-agent" tabindex="-1"><code>update_agent</code> <a class="header-anchor" href="#update-agent" aria-label="Permalink to “update_agent”">​</a></h3><p>🛡 — Rename, relabel, or drain: <code>no_schedule: true</code> lets the agent finish what it has and take nothing new, which is how you take its host down safely.</p><p>Parameters: <code>agent_id</code>, <code>org_id</code>, <code>name</code>, <code>no_schedule</code>, <code>custom_labels</code>.</p><h3 id="delete-agent" tabindex="-1"><code>delete_agent</code> <a class="header-anchor" href="#delete-agent" aria-label="Permalink to “delete_agent”">​</a></h3><p>🛡👤 — Removes an agent and invalidates its token. Anything it was running is lost and has to be restarted; drain it first.</p><p>Parameters: <code>agent_id</code>, <code>org_id</code>, <code>confirm_token</code>.</p><h2 id="forges" tabindex="-1">Forges <a class="header-anchor" href="#forges" aria-label="Permalink to “Forges”">​</a></h2><p>The OAuth configuration every login and every repository read depends on. The client secret is write-only: Woodpecker declares it <code>json:&quot;-&quot;</code> and never returns it.</p><h3 id="list-forges" tabindex="-1"><code>list_forges</code> <a class="header-anchor" href="#list-forges" aria-label="Permalink to “list_forges”">​</a></h3><p>🛡 — Forges this instance authenticates against. The <code>forge_id</code> shown here is what <code>get_user</code> and <code>delete_user</code> require.</p><p>Parameters: <code>page</code>, <code>per_page</code>.</p><h3 id="get-forge" tabindex="-1"><code>get_forge</code> <a class="header-anchor" href="#get-forge" aria-label="Permalink to “get_forge”">​</a></h3><p>🛡 — One forge configuration.</p><p>Parameters: <code>forge_id</code>.</p><h3 id="create-forge" tabindex="-1"><code>create_forge</code> <a class="header-anchor" href="#create-forge" aria-label="Permalink to “create_forge”">​</a></h3><p>🛡 — Registers an additional forge. The OAuth application has to exist on the forge side first, with this Woodpecker as its callback. <code>url</code> and <code>oauth_host</code> must be absolute http(s) URLs.</p><p>Parameters: <code>type</code>, <code>url</code>, <code>client</code>, <code>oauth_client_secret</code>, <code>oauth_host</code>, <code>skip_verify</code>.</p><h3 id="update-forge" tabindex="-1"><code>update_forge</code> <a class="header-anchor" href="#update-forge" aria-label="Permalink to “update_forge”">​</a></h3><p>🛡👤 — Changes a forge configuration. Two-step because a wrong value locks everyone out of the instance, including whoever is fixing it — the web UI is behind the login this setting controls.</p><p>Parameters: <code>forge_id</code>, <code>type</code>, <code>url</code>, <code>client</code>, <code>oauth_client_secret</code>, <code>oauth_host</code>, <code>skip_verify</code>, <code>confirm_token</code>.</p><h3 id="delete-forge" tabindex="-1"><code>delete_forge</code> <a class="header-anchor" href="#delete-forge" aria-label="Permalink to “delete_forge”">​</a></h3><p>🛡👤 — Removes a forge. Everyone who signs in through it loses access, and its repositories can no longer be read.</p><p>Parameters: <code>forge_id</code>, <code>confirm_token</code>.</p><h2 id="server-and-queue" tabindex="-1">Server and queue <a class="header-anchor" href="#server-and-queue" aria-label="Permalink to “Server and queue”">​</a></h2><h3 id="get-server-info" tabindex="-1"><code>get_server_info</code> <a class="header-anchor" href="#get-server-info" aria-label="Permalink to “get_server_info”">​</a></h3><p>Woodpecker&#39;s version and whether it reports itself healthy. Works <strong>without a token</strong>, which makes it the call to use when nothing else does: if it answers, <code>WOODPECKER_URL</code> is right and the problem is the token.</p><p>No parameters.</p><h3 id="get-queue-info" tabindex="-1"><code>get_queue_info</code> <a class="header-anchor" href="#get-queue-info" aria-label="Permalink to “get_queue_info”">​</a></h3><p>🛡 — The server-side build queue and the agent statistics behind it. With <code>list_queued_pipelines</code> this is the whole answer to &quot;why is my build not starting&quot;.</p><p>No parameters.</p><h3 id="get-log-level" tabindex="-1"><code>get_log_level</code> <a class="header-anchor" href="#get-log-level" aria-label="Permalink to “get_log_level”">​</a></h3><p>🛡 — The server&#39;s current log level.</p><p>No parameters.</p><h3 id="pause-queue" tabindex="-1"><code>pause_queue</code> <a class="header-anchor" href="#pause-queue" aria-label="Permalink to “pause_queue”">​</a></h3><p>🛡👤 — Stops the server handing new work to agents. Running pipelines finish; everything else queues. Two-step because it is instance-wide and silent — nothing tells the people whose builds are queuing why.</p><p>Parameters: <code>confirm_token</code>.</p><h3 id="resume-queue" tabindex="-1"><code>resume_queue</code> <a class="header-anchor" href="#resume-queue" aria-label="Permalink to “resume_queue”">​</a></h3><p>🛡 — Lets the server schedule again. Queued pipelines start at once, so expect a burst.</p><p>No parameters.</p><h3 id="set-log-level" tabindex="-1"><code>set_log_level</code> <a class="header-anchor" href="#set-log-level" aria-label="Permalink to “set_log_level”">​</a></h3><p>🛡👤 (when silencing) — Changes the running server&#39;s log level without a restart. <code>debug</code> and <code>trace</code> are loud, and <code>trace</code> logs request bodies. Turning the logs <strong>down</strong> — <code>fatal</code>, <code>panic</code> or <code>disabled</code> — is two-step: <code>disabled</code> stops the server recording what happens next at all. Raising the level applies on the first call.</p><p>Parameters: <code>level</code>, <code>confirm_token</code>.</p>`,242)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};